-- MISIDE MITA SKY - iPad/Delta All-In-One V1
-- Safe-mode 1K six-face sky from the supplied ZIP.

local write = writefile
local custom = getcustomasset or getsynasset
if not (write and custom) then
    warn("[MITA SKY] writefile/getcustomasset unavailable")
    return
end

-- Pure-Lua Base64 decoder (no crypt dependency)
local b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local function b64decode(data)
    data = string.gsub(data, '[^'..b..'=]', '')
    return (data:gsub('.', function(x)
        if x == '=' then return '' end
        local r,f='',(b:find(x,1,true)-1)
        for i=6,1,-1 do
            r = r .. (f % 2^i - f % 2^(i-1) > 0 and '1' or '0')
        end
        return r
    end):gsub('%d%d%d?%d?%d?%d?%d?%d?', function(x)
        if #x ~= 8 then return '' end
        local c=0
        for i=1,8 do
            c = c + (x:sub(i,i)=='1' and 2^(8-i) or 0)
        end
        return string.char(c)
    end))
end

local DATA = {
bk=[[]],
dn=[[]],
ft=[[]],
lf=[[]],
rt=[[]],
up=[[]],
}
}

local props = {
    bk="SkyboxBk", dn="SkyboxDn", ft="SkyboxFt",
    lf="SkyboxLf", rt="SkyboxRt", up="SkyboxUp"
}

local assets = {}
for _,f in ipairs({"bk","dn","ft","lf","rt","up"}) do
    local ok,res = pcall(function()
        local fn = "mita_"..f..".tex"
        write(fn, b64decode(DATA[f]))
        return custom(fn)
    end)
    if ok then
        assets[f] = res
    else
        warn("[MITA SKY] "..f.." failed: "..tostring(res))
    end
    task.wait(0.08)
end

local Lighting = game:GetService("Lighting")

local function apply()
    local sky = Lighting:FindFirstChildOfClass("Sky")
    if not sky then
        sky = Instance.new("Sky")
        sky.Name = "MitaEmbeddedSky"
        sky.Parent = Lighting
    end
    for f,a in pairs(assets) do
        if a then
            pcall(function()
                sky[props[f]] = a
            end)
        end
    end
end

apply()

Lighting.ChildAdded:Connect(function(obj)
    if obj:IsA("Sky") then
        task.delay(0.2, apply)
    end
end)

task.spawn(function()
    for _,delayTime in ipairs({0.5,1.5,3,6,10}) do
        task.wait(delayTime)
        apply()
    end
end)

pcall(function()
    game:GetService("StarterGui"):SetCore("SendNotification",{
        Title="MiSide Mita Sky",
        Text="Six-face sky loaded",
        Duration=5
    })
end)
